Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public class TokenElevationCheck
{
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);

    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool GetTokenInformation(IntPtr TokenHandle, int TokenInformationClass, out int TokenInformation, int TokenInformationLength, out int ReturnLength);

    [DllImport("kernel32.dll")]
    static extern IntPtr GetCurrentProcess();

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CloseHandle(IntPtr hObject);

    const uint TOKEN_QUERY = 0x0008;
    const int TokenElevationType = 18;

    public static void Check()
    {
        IntPtr hToken;
        if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, out hToken))
        {
            Console.WriteLine("OpenProcessToken failed: " + Marshal.GetLastWin32Error());
            return;
        }

        int elevationType, returnLength;
        if (GetTokenInformation(hToken, TokenElevationType, out elevationType, 4, out returnLength))
        {
            string[] labels = { "", "Default", "Full", "Limited" };
            Console.WriteLine("TokenElevationType: " + labels[elevationType]);
        }


        CloseHandle(hToken);
    }
}
'@
[TokenElevationCheck]::Check()

